update public.learning_paths
set
  title = 'Hispanic Culture and Civilization',
  goal = 'Hispanic Culture and Civilization',
  summary = 'Students learn to interpret the histories, societies, arts, politics, identities, migrations, and cultural productions of the Spanish-speaking world through comparative, transatlantic, hemispheric, and ethically grounded analysis.',
  data = $hccvjson${"slug": "hispanic-culture-and-civilization", "title": "Hispanic Culture and Civilization", "description": "Students learn to interpret the histories, societies, arts, politics, identities, migrations, and cultural productions of the Spanish-speaking world through comparative, transatlantic, hemispheric, and ethically grounded analysis.", "topics": [{"id": "c92d99d9-2a93-4e08-9777-e8012190fe80", "type": "topic", "title": "What Is Hispanic? Regions, Terms, and Methods", "description": "Introduces the contested meanings of Hispanic, Latino/a/x, Latin American, Iberian, Caribbean, and transatlantic culture while teaching basic methods of cultural analysis.", "children": [{"id": "9ccfb5cf-69d9-429f-9870-a502cf54f1f3", "type": "subtopic", "title": "Key terms and geographic frames", "children": [{"id": "c6c88da1-c9a4-42e8-aedf-286ccb8ee159", "type": "concept", "title": "Hispanic, Latino/a/x, Latin American, Iberian, Chicano/a/x"}, {"id": "27309259-c2fa-4005-a131-7d35efe84520", "type": "concept", "title": "Spain, Spanish America, the Caribbean, Equatorial Guinea, and diaspora"}, {"id": "219cd3a7-4555-4507-8593-67218b768f54", "type": "concept", "title": "Language, empire, ethnicity, race, nation, and religion as overlapping categories"}], "description": "Students begin by learning that course vocabulary is historical and political, not neutral labeling."}, {"id": "c1a4b162-8c80-410a-9952-c8debea87254", "type": "subtopic", "title": "Cultural-analysis methods", "children": [{"id": "e35c39c8-36d2-4fef-baf3-e205237b87c5", "type": "concept", "title": "Close reading of images, texts, film, music, and ritual"}, {"id": "84e1112f-5428-44c2-89b5-8423cc195b0d", "type": "concept", "title": "Historical contextualization and comparison"}, {"id": "ee87ddfb-41f2-4e30-964b-97e560f4c16a", "type": "concept", "title": "Attention to power, audience, archive, genre, and translation"}], "description": "This subtopic gives students tools for reading objects, practices, spaces, and media as evidence."}, {"id": "f413b297-ad7e-493a-a3fc-8eabeb31c62d", "type": "subtopic", "title": "Spanish as a world language", "children": [{"id": "725c46ae-3a1e-4c7b-bd57-aab3e5d906b7", "type": "concept", "title": "Dialects and regional variation"}, {"id": "5cb33639-de5a-4683-a59f-45cd3de0c2ad", "type": "concept", "title": "Bilingualism, code-switching, and language prestige"}, {"id": "2c0172f9-f43c-4b82-815b-dad2163493f1", "type": "concept", "title": "Language policy and cultural institutions"}], "description": "Students connect language to migration, colonialism, education, media, and global cultural markets."}]}, {"id": "2e5ccf09-d419-4004-baa4-b8d3781a2d50", "type": "topic", "title": "Iberian Historical Foundations", "description": "Builds context for Roman, Visigothic, Islamic, Jewish, Christian, and early modern Iberian formations that shaped later Spanish-speaking worlds.", "children": [{"id": "f5f78707-04fc-40a8-9085-be913f20260b", "type": "subtopic", "title": "Ancient and medieval Iberia", "children": [{"id": "2d89f723-6c89-4410-b333-a2237638143f", "type": "concept", "title": "Roman Hispania and Latinization"}, {"id": "d79a80fe-d145-4d46-b399-96d84f9c2530", "type": "concept", "title": "Visigothic kingdoms and legal cultures"}, {"id": "52ea1a08-c0ba-49d8-9512-051168beb34c", "type": "concept", "title": "Regional identities and frontier societies"}], "description": "The point is to see Iberia as layered and plural before it becomes an imperial center."}, {"id": "279f535d-ede2-4a82-bafa-d0d1e7dffb99", "type": "subtopic", "title": "Al-Andalus and convivencia debates", "children": [{"id": "0cf3a890-fcf2-4385-8dfc-f45d3da6b82b", "type": "concept", "title": "Caliphate of Cordoba and Islamic urban culture"}, {"id": "2490ba3b-3e88-43ba-a967-cc0fdec763b6", "type": "concept", "title": "Hebrew, Arabic, and Romance intellectual exchange"}, {"id": "d99fbd5a-50e8-4f8a-b7b0-2396302cf922", "type": "concept", "title": "Historiographical debates over coexistence, hierarchy, and violence"}], "description": "Students examine Muslim, Jewish, and Christian Iberia without romanticizing or flattening conflict."}, {"id": "8bd89a30-0ba7-45aa-b904-04a58aa232ee", "type": "subtopic", "title": "1492 and early modern consolidation", "children": [{"id": "ae3ece8f-29f7-4fbf-95ea-8024d794a1a6", "type": "concept", "title": "Catholic Monarchs and state formation"}, {"id": "65ec61b0-5abf-4beb-b1f1-6c1fb38c872e", "type": "concept", "title": "Inquisition, limpieza de sangre, and religious policing"}, {"id": "d5845a02-574c-45e9-90d1-ba9e59bf3200", "type": "concept", "title": "Nebrija, language standardization, and imperial ambition"}], "description": "This section links the end of Granada, expulsion of Jews, grammar, print, and Atlantic expansion."}]}, {"id": "96943956-dff8-40cd-bf2e-5b846c21cdca", "type": "topic", "title": "Indigenous Worlds before 1492", "description": "Centers Mesoamerican, Andean, Caribbean, and other Indigenous civilizations as complex societies with their own political, scientific, artistic, and spiritual systems.", "children": [{"id": "3ba985c5-3848-40e5-9a21-79b090ef9ea4", "type": "subtopic", "title": "Mesoamerican civilizations", "children": [{"id": "2ad77bf7-4f6e-4ccb-88b7-9e38453a3a21", "type": "concept", "title": "Maya cities, writing, calendars, and astronomy"}, {"id": "9545f07e-7a45-4340-ba35-dc07d45fb0d2", "type": "concept", "title": "Mexica empire, tribute, ritual, and urban design"}, {"id": "a4a67e4d-149d-41aa-8435-0730918811fb", "type": "concept", "title": "Mixtec, Zapotec, and other regional traditions"}], "description": "Students study Indigenous societies as sophisticated political and cultural worlds, not prefaces to conquest."}, {"id": "337fd736-2e88-4d0c-a868-859f71cc401c", "type": "subtopic", "title": "Andean and circum-Caribbean worlds", "children": [{"id": "ede3b501-d2ec-4272-84a4-0866bf0aaee3", "type": "concept", "title": "Inka statecraft, roads, quipu, and reciprocity"}, {"id": "c84d9396-6549-4031-80ce-48a7008fc990", "type": "concept", "title": "Taino, Carib, and Caribbean exchange networks"}, {"id": "cf8e57fc-3711-4c5b-84bb-0a106371dd0c", "type": "concept", "title": "Agriculture, ecology, and sacred landscapes"}], "description": "This subtopic broadens the course beyond the usual Mexico-centered narrative."}, {"id": "b35ec316-39fc-48b8-8646-c57736e085fe", "type": "subtopic", "title": "Knowledge systems and cultural memory", "children": [{"id": "58060af0-2cef-46a7-bf4e-6158eaa7ebf7", "type": "concept", "title": "Codices, textiles, ceramics, architecture, and maps"}, {"id": "a44a41d1-6c18-450a-a17f-bf82847c734b", "type": "concept", "title": "Creation stories, cosmology, and ritual practice"}, {"id": "1728907b-91b9-433f-b13f-2936dceabc5f", "type": "concept", "title": "Ethnohistory and Indigenous-authored colonial texts"}], "description": "Students learn how material culture and oral traditions preserve intellectual histories."}]}, {"id": "49a23b2c-93f5-4b0d-97b3-7c5a70db3513", "type": "topic", "title": "Conquest, Colonization, and the Atlantic World", "description": "Examines encounter, violence, evangelization, extraction, law, translation, and cultural negotiation across Spain, the Americas, and Africa.", "children": [{"id": "5ced98d4-c5df-4b04-ac54-401fd80dbace", "type": "subtopic", "title": "Encounter and conquest narratives", "children": [{"id": "45e71b6b-eff6-4232-b2aa-3de63c0b44bb", "type": "concept", "title": "Columbus, Cortes, Las Casas, and Sahagun"}, {"id": "c97f5d38-ed12-4d4f-b268-c241d0d55096", "type": "concept", "title": "Malintzin/Maliche and translation"}, {"id": "274b2b80-d361-4ba4-bbd5-170c50286422", "type": "concept", "title": "Violence, alliance, disease, and contingency"}], "description": "Students compare Spanish, Indigenous, and later historical accounts to understand evidence and perspective."}, {"id": "1a4d085f-2778-419a-a932-f31570dad7cf", "type": "subtopic", "title": "Colonial institutions and social order", "children": [{"id": "0c4dc9a1-1a49-4f5b-ac82-ebc0b6e166d4", "type": "concept", "title": "Encomienda, repartimiento, mita, hacienda, and slavery"}, {"id": "515571a6-3adb-4348-8870-9a1780196f9d", "type": "concept", "title": "Viceroyalties, audiencias, cabildos, and colonial law"}, {"id": "29330403-7e4f-4a6c-9ace-fec850857a39", "type": "concept", "title": "Casta systems, legal categories, and everyday negotiation"}], "description": "This subtopic explains how empire governed labor, land, conversion, and status."}, {"id": "ee5b899f-d2e8-4d76-b8b4-6d7f37aa0e2f", "type": "subtopic", "title": "Atlantic exchange and hybrid cultures", "children": [{"id": "bcd90f67-672a-43ab-928b-23b2c74be427", "type": "concept", "title": "Silver, sugar, trade routes, and forced migration"}, {"id": "33da10f9-1695-4f40-ae00-8bce50515c73", "type": "concept", "title": "Evangelization, syncretism, and religious art"}, {"id": "9feee7f5-8ede-4be9-baf6-7ba90998cb9f", "type": "concept", "title": "Creole cultures, Baroque cities, and borderlands"}], "description": "Students connect empire to global flows of people, goods, beliefs, and forms."}]}, {"id": "b8c72aef-a1e9-41a6-a7a6-463cb83e5547", "type": "topic", "title": "Independence, Nation-Building, and Liberal Modernity", "description": "Connects Atlantic revolutions, independence wars, constitutions, regionalism, citizenship, caudillismo, and the uneven promises of modern nations.", "children": [{"id": "bb7154ee-7723-43a0-94f1-537e876596b2", "type": "subtopic", "title": "Atlantic revolutions and independence", "children": [{"id": "007cbea5-062e-4724-9123-05f4ded4be86", "type": "concept", "title": "Bourbon reforms and imperial crisis"}, {"id": "5edcd731-04df-4bd1-b5c7-819f004ca221", "type": "concept", "title": "Haiti, Spain, Spanish America, and Atlantic republicanism"}, {"id": "6cb8c9d2-eb7c-4b8b-ae6d-60d94fd0dc96", "type": "concept", "title": "Bolivar, San Martin, Hidalgo, Morelos, and local actors"}], "description": "Students learn why independence was regional, uneven, and socially contested."}, {"id": "a9ba0d30-157e-4851-9a73-a4275df3ac9d", "type": "subtopic", "title": "Citizenship and exclusion", "children": [{"id": "15c9557a-526f-4276-ab57-4932d02fbff2", "type": "concept", "title": "Constitutions, suffrage, and republican ideals"}, {"id": "866685c4-7c39-46bc-816d-7dfe4c80b485", "type": "concept", "title": "Indigenous communities, Afro-descendants, women, and peasants"}, {"id": "82d0557a-5792-43b4-b851-a598474e70cf", "type": "concept", "title": "Caudillismo, civil wars, and regional power"}], "description": "This section asks who gained rights in new nations and who remained marginalized."}, {"id": "00e32fd2-fdb7-412c-924f-2e5e580ce3ee", "type": "subtopic", "title": "Modernity, economy, and cultural nationalism", "children": [{"id": "6a591194-919c-4894-8ce5-ee9d3c59c766", "type": "concept", "title": "Liberalism, positivism, and modernization projects"}, {"id": "686ad91f-74a4-4ffd-bbe0-e0c72420979c", "type": "concept", "title": "Costumbrismo, romantic nationalism, and public monuments"}, {"id": "3dd540bb-efda-4e36-aa94-e354b6c5c254", "type": "concept", "title": "Land, labor, and uneven development"}], "description": "Students connect railroads, export economies, education, and print culture to national identity."}]}, {"id": "715f7f6e-3ec5-4433-883a-6954a5db50ea", "type": "topic", "title": "Race, Ethnicity, Mestizaje, and Afro-Hispanic Worlds", "description": "Studies racial formation, caste systems, slavery, Indigenous survival, Afro-descendant cultures, whitening ideologies, and debates over mestizaje.", "children": [{"id": "6804b2bb-71d8-4ad3-90c4-bd22b647535f", "type": "subtopic", "title": "Colonial race-making", "children": [{"id": "5272e62e-8874-45f1-a481-c332fb97aafe", "type": "concept", "title": "Casta paintings and racial taxonomies"}, {"id": "98200831-1f95-4705-a758-92169f95046f", "type": "concept", "title": "Slavery, freedom suits, and manumission"}, {"id": "51d69f1b-8c0a-4ee5-bd7a-869656f2595b", "type": "concept", "title": "Honor, limpieza de sangre, gender, and status"}], "description": "Students trace how race became a legal, economic, visual, and cultural system."}, {"id": "1c21d68c-6017-406a-a403-3efaad7f7dc1", "type": "subtopic", "title": "Mestizaje and national ideology", "children": [{"id": "ec7f1d14-d30c-47b9-ba9e-f90fac6f0e45", "type": "concept", "title": "Indigenismo and state cultural projects"}, {"id": "192633ef-3b80-4854-a77d-718d332518fd", "type": "concept", "title": "Whitening, assimilation, and anti-Blackness"}, {"id": "9441d4b8-ebfb-4d96-8c75-eacbf4edd409", "type": "concept", "title": "Mexico, Peru, Cuba, Dominican Republic, and comparative cases"}], "description": "This subtopic treats mestizaje as both cultural reality and political myth."}, {"id": "5a4a09b6-c927-4ada-955f-564e6cd15694", "type": "subtopic", "title": "Afro-Hispanic histories and cultures", "children": [{"id": "f16770e5-8c35-48be-84c6-1519afc169ce", "type": "concept", "title": "Afro-Caribbean religion, music, and performance"}, {"id": "cf83a202-7177-4092-bf5a-4ab047401f55", "type": "concept", "title": "Maroon communities and resistance"}, {"id": "fba1cdd7-f1bf-4cdd-b56a-b01eb99dbbca", "type": "concept", "title": "Abolition, citizenship, and contemporary Afro-Latin activism"}], "description": "Students foreground Black experience as central, not peripheral, to Hispanic civilization."}]}, {"id": "bb688156-0af1-4cc3-8a0c-bb680cb6f6dc", "type": "topic", "title": "Religion, Popular Culture, and Everyday Life", "description": "Explores Catholicism, syncretism, festivals, foodways, gendered customs, public rituals, and vernacular practices as living cultural systems.", "children": [{"id": "f3de0564-b2a5-4408-b103-da08cd6c2a60", "type": "subtopic", "title": "Catholicism and syncretic practice", "children": [{"id": "16813f02-0c99-4211-85a0-2a0f46604923", "type": "concept", "title": "Saints, Marian devotions, and pilgrimage"}, {"id": "baa82d5a-60d4-4497-9d68-6ea4ea97982c", "type": "concept", "title": "Virgin of Guadalupe and national symbolism"}, {"id": "e5878cd6-34f7-42b1-a8a6-b52aff389998", "type": "concept", "title": "Santeria, Candomble-adjacent comparisons, and local ritual forms"}], "description": "Students study religion as institution, worldview, art system, and everyday practice."}, {"id": "849b7470-2f4b-472d-b20a-d7e139d90031", "type": "subtopic", "title": "Festivals, foodways, and material life", "children": [{"id": "d2028f8a-b55c-4fcc-b640-47ecd34445fa", "type": "concept", "title": "Carnival, Semana Santa, Day of the Dead, and local fiestas"}, {"id": "f4b8ddb4-fbdf-4d67-a806-fd8d341d6658", "type": "concept", "title": "Cuisine, agriculture, migration, and class"}, {"id": "2aa83e03-5316-4ea0-8183-e5c80a2e890e", "type": "concept", "title": "Dress, craft, markets, and domestic space"}], "description": "This section helps students analyze ordinary practices as archives of history and identity."}, {"id": "f593caa5-7c57-4b11-97cc-82d4026e7611", "type": "subtopic", "title": "Gender, family, and social customs", "children": [{"id": "25813453-f0cf-483b-8570-810b546f710d", "type": "concept", "title": "Machismo, marianismo, and feminist critiques"}, {"id": "8a8c091e-006a-4d81-ab42-6fd67cdba40e", "type": "concept", "title": "Kinship, honor, sexuality, and generational change"}, {"id": "e2c0ba7a-5004-4d6f-b612-0f6b53a0dd8c", "type": "concept", "title": "Youth culture, sport, leisure, and urban life"}], "description": "Students examine how public and private life reproduce or challenge social norms."}]}, {"id": "d67c3021-84bb-456c-8654-0f57bca322a7", "type": "topic", "title": "Art, Architecture, Music, Film, and Visual Culture", "description": "Uses cultural objects to read power, identity, taste, nationalism, resistance, memory, and globalization across the Spanish-speaking world.", "children": [{"id": "820f0b44-4c46-42b3-8beb-c89c5b85072f", "type": "subtopic", "title": "Art and architecture", "children": [{"id": "ca9ca7c4-8ffb-4d51-b90c-9ae5d2d066af", "type": "concept", "title": "Alhambra, cathedrals, missions, plazas, and colonial cities"}, {"id": "5125d54d-b4ce-44ab-828c-74aab51651d4", "type": "concept", "title": "Velazquez, Goya, Picasso, Kahlo, Rivera, Lam, and contemporary artists"}, {"id": "ad1dcf54-92f5-4efe-bc26-95f5c2a091ff", "type": "concept", "title": "Museum practice, repatriation, and public art"}], "description": "Students learn to interpret visual form in relation to patronage, ideology, memory, and place."}, {"id": "3c1f09ee-4848-469e-8647-f2d20d85ce44", "type": "subtopic", "title": "Music and performance", "children": [{"id": "cde944aa-6275-48bc-9b3e-126ab55c0422", "type": "concept", "title": "Flamenco, son, salsa, tango, corrido, reggaeton, nueva cancion"}, {"id": "77564ccb-91b3-4476-b4a5-d437a6b804eb", "type": "concept", "title": "Performance, dance, oral tradition, and protest"}, {"id": "fc1b970c-5705-49ae-8204-62b492193ba4", "type": "concept", "title": "Commercialization, appropriation, and global circulation"}], "description": "This subtopic treats music as a map of migration, race, class, and regional identity."}, {"id": "47b289ab-2730-49d8-931a-f6f3ce71aa0e", "type": "subtopic", "title": "Film, television, and digital media", "children": [{"id": "451ac809-4efb-44e8-9415-6a29a06894b2", "type": "concept", "title": "New Latin American Cinema and Spanish post-Franco film"}, {"id": "2a8c65a5-d126-4b37-b4ea-4ec639ac01a3", "type": "concept", "title": "Telenovelas, streaming, and popular genres"}, {"id": "76a4e3cc-8852-47aa-9cb1-69a3c1fce2db", "type": "concept", "title": "Documentary, social media, and cultural memory"}], "description": "Students analyze audiovisual culture as narrative, industry, and social critique."}]}, {"id": "1cc5c45c-c493-44b6-9e9e-d28d027fa2f6", "type": "topic", "title": "Dictatorship, Democracy, Revolution, and Memory", "description": "Compares authoritarianism, revolution, civil conflict, human rights, truth commissions, monuments, archives, and memory cultures.", "children": [{"id": "0b975822-062d-